 if(action==='find-person'){const target=el.dataset.target,q=document.querySelector(`[data-person-query="${target}"]`).value.trim(),results=document.querySelector(`[data-person-results="${target}"]`);if(!q){results.textContent=t('enterSearch');return;}const data=await api(endpoint('/persons?q='+encodeURIComponent(q)));results.innerHTML=data.items.filter(p=>p.status!=='ARCHIVED').map(p=>`<button type="button" data-action="pick-person" data-target="${target}" data-id="${p.id}" data-label="${esc(name(p)+' · '+p.code)}">${esc(name(p))}<small>${esc(p.code)} · ${esc([p.nativeVillage,p.currentCity].filter(Boolean).join(' · '))}</small></button>`).join('')||`<p>${t('empty')}</p>`;}
