 if(action==='zoom-in'||action==='zoom-out'){treeScale=Math.max(.5,Math.min(1.8,treeScale+(action==='zoom-in'?.15:-.15)));$('.tree').style.zoom=treeScale;}
 if(action==='collapse'){const collapsed=el.dataset.collapsed==='true';document.querySelectorAll('[data-relative]').forEach(n=>n.hidden=!collapsed);el.dataset.collapsed=String(!collapsed);el.textContent=t(collapsed?'collapse':'expand');}
 if(action==='print'){const pl=$('[name="print-language"]').value,exported=await api(endpoint('/'+currentProfile.resource+'/'+currentProfile.id+'/export'));$('#print-document')?.remove();const people=[...(exported.members||[]),...(exported.relatives||[])],all=[exported.family||exported.person,...people];$('#app').insertAdjacentHTML('beforeend',`<section id="print-document"><div class="print-title"><h1>${t('title')}</h1><p>${esc(samaj.name)}</p></div>${all.map(p=>`<article><h2>${esc(name(p))}</h2>${p.kind==='person'&&p.photo?`<img class="profile-photo" src="/api/digital-samaj${endpoint('/photos/'+p.photo)}" alt="">`:''}${details(p,pl)}</article>`).join('')}<table><tbody>${(exported.relationships||[]).map(e=>`<tr><td>${esc(name(people.find(p=>p.id===e.personId)||{}))}</td><td>${esc(pl==='both'?(SamajStrings.en[e.type]||e.type)+' / '+(SamajStrings.hi[e.type]||e.type):(SamajStrings[pl][e.type]||e.type))}</td><td>${esc(name(people.find(p=>p.id===e.relatedId)||{}))}</td></tr>`).join('')}</tbody></table></section>`);await Promise.all([...$('#print-document').querySelectorAll('img')].map(img=>img.decode().catch(()=>{})));document.body.dataset.printing='true';window.print();}
