 if(action==='moderation'){const r=await api(endpoint('/moderation'));$('#admin-extra').innerHTML=`<h3>${t('moderation')}</h3>${r.items.map(m=>`<article class="card"><p>${esc(m.body)}</p><p>${esc(m.reason)}</p><small>${esc(m.status)}</small>${button('REVIEWED','report-decision',`data-id="${m.id}" data-status="REVIEWED"`)}${button('DISMISSED','report-decision',`data-id="${m.id}" data-status="DISMISSED"`)}</article>`).join('')}`;}
 if(action==='report-decision'){await api(endpoint('/moderation/'+el.dataset.id),'POST',{status:el.dataset.status});notice(t('saved'));}
 if(action==='commit-import'){const r=await api(endpoint('/imports/'+importJob+'/commit'),'POST',{});$('#import-preview').innerHTML=`<div class="card">${details(r)}</div>`;}
